import XCTest

final class TapTests: XCTestCase {
    func testOpenCreateRoomMenu() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        Thread.sleep(forTimeInterval: 1.5)

        let buttons = app.buttons.allElementsBoundByIndex
        for (i, b) in buttons.enumerated() {
            NSLog("TAPTEST button[\(i)] label=%@ id=%@ frame=%@", b.label, b.identifier, NSStringFromCGRect(b.frame))
        }

        var best: XCUIElement? = nil
        var bestScore = -Double.greatestFiniteMagnitude
        for b in buttons {
            let f = b.frame
            guard f.width > 1, f.height > 1 else { continue }
            let score = f.midX + f.midY
            if score > bestScore {
                bestScore = score
                best = b
            }
        }
        if let b = best {
            NSLog("TAPTEST tapping bottom-right button frame=%@", NSStringFromCGRect(b.frame))
            b.tap()
        } else {
            NSLog("TAPTEST fallback coordinate tap")
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.93, dy: 0.93)).tap()
        }
        Thread.sleep(forTimeInterval: 2.0)
    }
}

